import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_matvec(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__global__ void cute_matvec_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M,
    int K,
    bool vectorized)
{
    constexpr int ROWS_PER_BLOCK = 8;
    constexpr int TILE_K = 1024;
    constexpr int SPLIT_K = 1;
    const int tid = threadIdx.x;
    const int lane = tid & 31;
    const int warp = tid >> 5;
    const int row = blockIdx.x * ROWS_PER_BLOCK + warp;
    const int split = blockIdx.y;
    const int chunk_size = ((K + SPLIT_K * 4 - 1) / (SPLIT_K * 4)) * 4;
    const int chunk_begin = min(split * chunk_size, K);
    const int chunk_end = min(chunk_begin + chunk_size, K);
    __shared__ float b_tile[TILE_K];
    float sum = 0.0f;
    for (int tile_start = chunk_begin; tile_start < chunk_end; tile_start += TILE_K) {
        if (vectorized) {
            const int tile_k = tid * 4;
            if (tile_k + 3 < TILE_K) {
                const int global_k = tile_start + tile_k;
                if (global_k + 3 < chunk_end) {
                    const float4 b_value =
                        reinterpret_cast<const float4*>(B + global_k)[0];
                    b_tile[tile_k + 0] = b_value.x;
                    b_tile[tile_k + 1] = b_value.y;
                    b_tile[tile_k + 2] = b_value.z;
                    b_tile[tile_k + 3] = b_value.w;
                } else {
                    b_tile[tile_k + 0] = 0.0f;
                    b_tile[tile_k + 1] = 0.0f;
                    b_tile[tile_k + 2] = 0.0f;
                    b_tile[tile_k + 3] = 0.0f;
                }
            }
        } else {
            for (int tile_k = tid; tile_k < TILE_K; tile_k += blockDim.x) {
                const int k = tile_start + tile_k;
                b_tile[tile_k] = (k < chunk_end && k < K) ? B[k] : 0.0f;
            }
        }
        __syncthreads();
        const int tile_count = min(TILE_K, chunk_end - tile_start);
        if (row < M) {
            if (vectorized) {
                for (int tile_k = lane * 4; tile_k + 3 < tile_count; tile_k += 128) {
                    const float4 a_value = reinterpret_cast<const float4*>(
                        A + static_cast<long long>(row) * K + tile_start + tile_k)[0];
                    sum = fmaf(a_value.x, b_tile[tile_k + 0], sum);
                    sum = fmaf(a_value.y, b_tile[tile_k + 1], sum);
                    sum = fmaf(a_value.z, b_tile[tile_k + 2], sum);
                    sum = fmaf(a_value.w, b_tile[tile_k + 3], sum);
                }
            } else {
                for (int tile_k = lane; tile_k < tile_count; tile_k += 32) {
                    sum = fmaf(
                        A[static_cast<long long>(row) * K + tile_start + tile_k],
                        b_tile[tile_k],
                        sum);
                }
            }
        }
        __syncthreads();
    }
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum += __shfl_down_sync(0xffffffff, sum, offset);
    }
    if (lane == 0 && row < M) {
        C[row] = sum;
    }
}

torch::Tensor cute_matvec(torch::Tensor A, torch::Tensor B)
{
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dim() == 2, "A must be a 2D tensor");
    TORCH_CHECK(B.dim() == 2, "B must be a 2D tensor");
    TORCH_CHECK(A.scalar_type() == at::kFloat, "A must be float32");
    TORCH_CHECK(B.scalar_type() == at::kFloat, "B must be float32");
    TORCH_CHECK(B.size(1) == 1, "B must have shape (K, 1)");
    TORCH_CHECK(A.size(1) == B.size(0), "Incompatible matrix dimensions");

    auto A_contiguous = A.contiguous();
    auto B_contiguous = B.contiguous();

    const int M = static_cast<int>(A_contiguous.size(0));
    const int K = static_cast<int>(A_contiguous.size(1));
    auto C = torch::empty({M, 1}, A_contiguous.options());
    constexpr int threads = 256;
    constexpr int split_k = 1;
    const dim3 grid((M + 7) / 8, split_k);
    const dim3 block(threads);
    const bool vectorized =
        (K % 4 == 0) &&
        ((reinterpret_cast<unsigned long long>(A_contiguous.data_ptr<float>()) & 15ULL) == 0) &&
        ((reinterpret_cast<unsigned long long>(B_contiguous.data_ptr<float>()) & 15ULL) == 0);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    TORCH_CHECK(
        cudaMemsetAsync(C.data_ptr<float>(), 0,
                        static_cast<size_t>(M) * sizeof(float), stream) == cudaSuccess,
        "CUTE matrix-vector output initialization failed");
    cute_matvec_kernel<<<grid, block, 0, stream>>>(
        A_contiguous.data_ptr<float>(),
        B_contiguous.data_ptr<float>(),
        C.data_ptr<float>(),
        M,
        K,
        vectorized);

    TORCH_CHECK(
        cudaGetLastError() == cudaSuccess,
        "CUTE matrix-vector kernel launch failed");

    return C;
}
"""

cute_ext = load_inline(
    name="cute_matvec_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_matvec"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self._ext = cute_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_matvec(A, B)

